'use strict';

const fs = require('fs');
const path = require('path');

const DIR = __dirname;
const SOURCES = ['a.txt', 'b.txt', 'c.txt'];

function readSource(name) {
  const full = path.join(DIR, name);
  const raw = fs.readFileSync(full, 'utf8');
  // Population line: "<Label> population: <integer>"
  const numbers = raw.match(/-?\d+(?:\.\d+)?/g) || [];
  if (numbers.length !== 1) {
    throw new Error(`${name}: expected exactly one numeric population, found ${numbers.length}`);
  }
  const value = Number(numbers[0]);
  if (!Number.isInteger(value)) {
    throw new Error(`${name}: population "${numbers[0]}" is not an integer`);
  }
  const label = raw.split('population')[0].trim();
  return { name, path: full, label, value, raw: raw.trim() };
}

const populations = SOURCES.map(readSource);

// Cross-check 1: every file yields a distinct, non-conflicting population
// (re-read from disk and re-parse to prove the parse is stable, not stored state).
for (const p of populations) {
  const again = readSource(p.name);
  if (again.value !== p.value) {
    throw new Error(`cross-check failed: ${p.name} gave ${p.value} then ${again.value}`);
  }
}

// Cross-check 2: two independent aggregations must agree.
const sumReduce = populations.reduce((acc, p) => acc + p.value, 0);
let sumLoop = 0;
for (const p of populations) sumLoop += p.value;
const sumBigInt = populations
  .map((p) => BigInt(p.value))
  .reduce((acc, v) => acc + v, 0n);
if (sumReduce !== sumLoop || BigInt(sumReduce) !== sumBigInt) {
  throw new Error(`cross-check failed: ${sumReduce} vs ${sumLoop} vs ${sumBigInt}`);
}

const answer = { total: sumReduce };
fs.writeFileSync(path.join(DIR, 'answer.json'), JSON.stringify(answer) + '\n', 'utf8');

console.log('sources read:');
for (const p of populations) {
  console.log(`  ${p.path} -> ${p.label} population = ${p.value} (raw: ${JSON.stringify(p.raw)})`);
}
console.log(`sum (reduce)  = ${sumReduce}`);
console.log(`sum (for-loop)= ${sumLoop}`);
console.log(`sum (BigInt)  = ${sumBigInt}`);
console.log('answer.json written:', JSON.stringify(answer));

